    const training = { fighter: "\u0413\u043E\u0434\u044B \u0441\u043B\u0443\u0436\u0431\u044B \u043D\u0430\u0443\u0447\u0438\u043B\u0438 \u0442\u0435\u0431\u044F \u0434\u0435\u0440\u0436\u0430\u0442\u044C \u0441\u0442\u0440\u043E\u0439 \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044C \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0439.", rogue: "\u0422\u044B \u043D\u0430\u0443\u0447\u0438\u043B\u0441\u044F \u0437\u0430\u043C\u0435\u0447\u0430\u0442\u044C \u0442\u0430\u0439\u043D\u0438\u043A\u0438, \u0447\u0438\u0442\u0430\u0442\u044C \u043B\u044E\u0434\u0435\u0439 \u0438 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u044C \u043E\u0431\u0445\u043E\u0434\u043D\u044B\u0435 \u043F\u0443\u0442\u0438.", wizard: "\u041E\u0431\u0443\u0447\u0435\u043D\u0438\u0435 \u043C\u0430\u0433\u0438\u0438 \u0434\u0430\u043B\u043E \u0442\u0435\u0431\u0435 \u043F\u0435\u0440\u0432\u044B\u0435 \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F \u0438 \u043F\u0440\u0438\u0432\u044B\u0447\u043A\u0443 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u043D\u0435\u043F\u043E\u043D\u044F\u0442\u043D\u043E\u0435.", cleric: "\u041F\u043E\u043C\u043E\u0433\u0430\u044F \u043B\u044E\u0434\u044F\u043C \u043F\u0440\u0438 \u0445\u0440\u0430\u043C\u0435, \u0442\u044B \u043E\u0431\u0440\u0451\u043B \u0432\u0435\u0440\u0443 \u0438 \u043F\u0435\u0440\u0432\u044B\u0435 \u0441\u0438\u043B\u044B \u0438\u0441\u0446\u0435\u043B\u0435\u043D\u0438\u044F." }[id];
